"""Write the endpoint reference from the same table the HTTP boundary enforces."""
from __future__ import annotations

import argparse
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))


def generated() -> str:
    """Describe transport contracts; domain validation still supplies readable errors."""
    from hoard import server
    lines = ["# Local HTTP API", "",
             "Generated by `python scripts/build_api_docs.py`; edit registrations in `hoard/api/`.", "",
             "All API data needs this run's access key. Changing endpoints require JSON POST from loopback.",
             "The two handshake endpoints use a one-time entry token or the private running-instance token.",
             "Image/file prefixes also accept a key in the address because image elements cannot set headers.", "",
             "Request fields are optional at the transport boundary; each handler validates its own operation.",
             "Shared action handlers list the union of their fields. `any` denotes a JSON value whose accepted",
             "shape depends on the action. Responses describe the top-level JSON type or media type; errors",
             "are JSON objects with an `error` string. See the handler for action-specific fields and errors.", "",
             "| Method | Path | Auth | Changes data | Request fields | Response |",
             "| --- | --- | --- | --- | --- | --- |"]
    for route in sorted(server.api_routes.ROUTES, key=lambda r: (r.path, r.method)):
        fields = ", ".join(f"`{key}: {kind}`" for key, kind in route.request) or "—"
        lines.append(f"| {route.method} | `{route.path}` | {route.auth} | {'yes' if route.changes else 'no'} | {fields} | {route.response} |")
    return "\n".join(lines) + "\n"


def main() -> int:
    """Generate the checked-in reference, or fail if registrations changed without it."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path, text = ROOT / "docs/API.md", generated()
    if args.check:
        return int(not path.exists() or path.read_text("utf-8") != text)
    path.write_text(text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
